package com.turboio.addon;
import java.io.*;import java.util.*;import java.util.concurrent.*;import java.lang.reflect.*;import android.app.*;import android.content.*;import android.net.*;import android.os.*;

/** Real picker adapter, substituted Android/network/Keystore and ZIP boundary. */
public final class MaterialAudioExportLifecycleTest {
 static final String ACCOUNT="a".repeat(64);static int checks;
 static void yes(boolean value){checks++;if(!value)throw new AssertionError("picker check "+checks);}
 static void idle()throws Exception{Field f=MaterialAudioExport.class.getDeclaredField("IO");f.setAccessible(true);for(int pass=0;pass<2;pass++)((ExecutorService)f.get(null)).submit(()->{}).get(5,TimeUnit.SECONDS);}
 static Bundle args(boolean remote){Bundle b=new Bundle();b.putString("id","draft");b.putString("account",ACCOUNT);b.putBoolean("remote",remote);if(remote)b.putString("fingerprint","target");return b;}
 static void reset(){LifelogAudioRuntime.actual=ACCOUNT;AudioSettings.value=new AudioConfig(ACCOUNT,"target",System.currentTimeMillis()+60000);AudioSettings.loads=0;AudioReadHttp.requests=0;AudioReadHttp.after=()->{};AudioRemoteExport.verifies=0;AudioRemoteExport.denied=false;LifelogAudioExport.copies=0;LifelogAudioExport.removes=0;android.widget.Toast.messages.clear();}
 static void load(Context app,Bundle b)throws Exception{Method f=MaterialAudioExport.class.getDeclaredMethod("load",Context.class,Bundle.class);f.setAccessible(true);try{f.invoke(null,app,b);}catch(InvocationTargetException e){throw (Exception)e.getCause();}}
 static void reject(String code,Context app,Bundle b)throws Exception{try{load(app,b);throw new AssertionError("accepted "+code);}catch(IOException expected){yes(code.equals(expected.getMessage()));}}
 static MaterialAudioExport picker(Activity a,boolean remote){MaterialAudioExport f=new MaterialAudioExport();f.activity=a;f.setArguments(args(remote));f.onCreate(null);return f;}
 public static void main(String[] argv)throws Exception{try{
  reset();Activity a=new Activity();load(a,args(true));yes(AudioRemoteExport.verifies==1&&AudioReadHttp.requests==1&&a.resolver.opens==0);
  reset();AudioSettings.value=new AudioConfig(ACCOUNT,"changed",System.currentTimeMillis()+60000);reject("AUDIO_CONNECTION_CHANGED",a,args(true));yes(AudioReadHttp.requests==0);
  reset();AudioSettings.value=new AudioConfig("b".repeat(64),"target",System.currentTimeMillis()+60000);reject("OFFICIAL_ACCOUNT_CHANGED",a,args(true));yes(AudioReadHttp.requests==0);
  reset();LifelogAudioRuntime.actual="other";reject("OFFICIAL_ACCOUNT_CHANGED",a,args(true));yes(AudioSettings.loads==0&&AudioReadHttp.requests==0);
  reset();AudioSettings.value=new AudioConfig(ACCOUNT,"target",1);reject("AUDIO_CREDENTIAL_EXPIRED",a,args(true));yes(AudioReadHttp.requests==0);
  reset();AudioSettings.value=null;reject("AUDIO_CONFIG_REQUIRED",a,args(true));yes(AudioReadHttp.requests==0);load(a,args(false));yes(AudioSettings.loads==1&&AudioRemoteExport.verifies==0);
  reset();AudioReadHttp.after=()->AudioSettings.value=new AudioConfig(ACCOUNT,"changed",System.currentTimeMillis()+60000);reject("AUDIO_CONNECTION_CHANGED",a,args(true));yes(AudioReadHttp.requests==1&&a.resolver.opens==0);
  reset();AudioRemoteExport.denied=true;reject("AUDIO_AUTH_REQUIRED",a,args(true));yes(a.resolver.opens==0);
  reset();AudioSettings.value=null;MaterialAudioExport.saveRemote(a,ACCOUNT,new MaterialCatalog.Entry());idle();yes(a.manager.added==null&&a.resolver.opens==0);yes(android.widget.Toast.messages.stream().anyMatch(s->s.contains("独立原音连接")));
  reset();MaterialAudioExport.saveRemote(a,ACCOUNT,new MaterialCatalog.Entry());idle();yes(a.manager.added!=null&&a.manager.added.getArguments().getBoolean("remote")&&"target".equals(a.manager.added.getArguments().getString("fingerprint")));yes(a.resolver.opens==0);a.manager.added=null;
  reset();a=new Activity();MaterialAudioExport f=picker(a,true);f.onActivityCreated(null);idle();yes(a.pickers==1&&a.resolver.opens==0);f.onActivityResult(14533,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://synthetic/destination")));idle();yes(a.resolver.opens==1&&Arrays.equals(a.resolver.bytes.toByteArray(),new byte[]{1,2,3})&&LifelogAudioExport.copies==1);yes(AudioRemoteExport.verifies==2&&LifelogAudioExport.removes==1);yes(android.widget.Toast.messages.stream().anyMatch(s->s.contains("已保存到所选位置")));
  reset();a=new Activity();f=picker(a,true);f.onActivityCreated(null);idle();AudioRemoteExport.denied=true;f.onActivityResult(14533,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://synthetic/destination")));idle();yes(a.resolver.opens==0&&LifelogAudioExport.copies==0&&LifelogAudioExport.removes==1);
  reset();a=new Activity();f=picker(a,true);f.onActivityCreated(null);idle();AudioSettings.value=new AudioConfig(ACCOUNT,"changed",System.currentTimeMillis()+60000);f.onActivityResult(14533,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://synthetic/destination")));idle();yes(a.resolver.opens==0&&LifelogAudioExport.copies==0);
  reset();a=new Activity();f=picker(a,true);f.onActivityCreated(null);idle();int before=AudioRemoteExport.verifies;f.onActivityResult(14533,0,null);idle();yes(a.resolver.opens==0&&AudioRemoteExport.verifies==before&&LifelogAudioExport.removes==1);
  reset();a=new Activity();f=picker(a,true);Bundle saved=new Bundle();f.onSaveInstanceState(saved);saved.putBoolean("launched",true);MaterialAudioExport resumed=picker(a,true);resumed.onCreate(saved);AudioSettings.value=new AudioConfig(ACCOUNT,"changed",System.currentTimeMillis()+60000);resumed.onActivityCreated(saved);idle();yes(a.pickers==0&&a.resolver.opens==0&&LifelogAudioExport.removes==1);
  System.out.println("Material audio picker lifecycle: "+checks+" checks passed");System.exit(0);
 }catch(Throwable error){error.printStackTrace();System.exit(1);}}
}
class MaterialCatalog {static class Entry {String id="rayneo-lifelog-synthetic";}}
class LifelogAudioArchive {interface Guard {void check()throws IOException;}}
class AudioConnection {long expiresAt;AudioConnection(long expires){expiresAt=expires;}}
class AudioConfig {final String account,fp;final AudioConnection connection;AudioConfig(String account,String fp,long expires){this.account=account;this.fp=fp;connection=new AudioConnection(expires);}String fingerprint(){return fp;}}
class AudioSettings {static AudioConfig value;static int loads;AudioSettings(Context app){}AudioConfig load(){loads++;return value;}}
class LifelogAudioRuntime {static String actual;interface Frozen {void done(List<Object> sessions,List<Object> archives,String error);}static void account(String account)throws IOException{if(!account.equals(actual))throw new IOException("OFFICIAL_ACCOUNT_CHANGED");}static void freeze(String a,String m,Frozen done){done.done(Collections.emptyList(),Collections.emptyList(),"");}}
class MaterialApi {interface Transport {Response exchange(String p,byte[] b)throws IOException;void cancel();}static class Response {}}
class AudioReadHttp implements MaterialApi.Transport {static int requests;static Runnable after=()->{};AudioReadHttp(AudioConnection c){}public MaterialApi.Response exchange(String p,byte[] b){requests++;after.run();return new MaterialApi.Response();}public void cancel(){}}
class LifelogAudioExport {interface Decoder {}interface Decoders {Decoder open()throws IOException;}static int copies,removes;static class Draft {String id="draft",account=MaterialAudioExportLifecycleTest.ACCOUNT,title="synthetic.zip";}static Draft load(File cache,String id,String account,long now){return new Draft();}static Draft prepare(File files,File cache,String account,String id,List<Object> sessions,List<Object> archives,Decoders decoders,LifelogAudioArchive.Guard g,long now)throws IOException{g.check();return new Draft();}static void copy(Draft draft,OutputStream out,LifelogAudioArchive.Guard g)throws IOException{g.check();copies++;out.write(new byte[]{1,2,3});g.check();}static void remove(File c,String id){removes++;}}
class Host107OpusFileDecoder implements LifelogAudioExport.Decoder {Host107OpusFileDecoder(){}}
class AudioRemoteExport {static int verifies;static boolean denied;static LifelogAudioExport.Draft prepare(File cache,AudioConfig cfg,String material,List<Object> local,MaterialApi.Transport http,LifelogAudioExport.Decoders d,LifelogAudioArchive.Guard g,java.util.function.LongSupplier clock)throws IOException{g.check();http.exchange("/identity",null);return new LifelogAudioExport.Draft();}static void verify(File cache,LifelogAudioExport.Draft draft,AudioConfig cfg,MaterialApi.Transport http,LifelogAudioArchive.Guard g,java.util.function.LongSupplier clock)throws IOException{verifies++;g.check();http.exchange("/identity",null);if(denied)throw new IOException("AUDIO_AUTH_REQUIRED");}}
